/* @autogenerated */
import { computed, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { BehaviorSubject, of } from 'rxjs';
import { RuntimeConfigService } from '@shared/context/config/app-config.service';
import { AppStateService } from '@shared/context/state/app-state.service';
import { ANONYMOUS_USER, UserInfo } from '@shared/context/identity/user-info.model';
import { DEFAULT_CACHE_TTL, RepositoryStore } from './repository-store.service';
import { RepositoryService } from './repository.service';
import { RepositoryProvider, Slide } from './provider/repository-provider.interface';

describe('RepositoryStore', () => {
  let cacheTtl: ReturnType<typeof signal<unknown>>;
  let tenant: BehaviorSubject<string>;
  let users: Record<string, BehaviorSubject<UserInfo>>;

  beforeEach(() => {
    cacheTtl = signal<unknown>(undefined);
    tenant = new BehaviorSubject('main');
    users = { main: new BehaviorSubject<UserInfo>(ANONYMOUS_USER), other: new BehaviorSubject(ANONYMOUS_USER) };
    const config = {
      value: (path: string) => computed(() => (path === 'data.cache-ttl' ? cacheTtl() : undefined)),
      value$: (path: string) => of(path === 'identity' ? { main: {}, other: {} } : undefined),
    };
    TestBed.configureTestingModule({
      providers: [
        { provide: RuntimeConfigService, useValue: config },
        { provide: AppStateService, useValue: { tenant, userInfo: users } },
      ],
    });
  });

  function filled(): RepositoryStore {
    const store = TestBed.inject(RepositoryStore);
    const cache = store.of('items');
    cache.listMap['{}'] = { cache: {} as any, observers: 1, query: {} };
    cache.resourceMap['1'] = { cache: {} as any, observers: 1 };
    cache.resourceAclData['--'] = { cache: {} as any, observers: 1 };
    return store;
  }

  function isEmpty(store: RepositoryStore): boolean {
    const cache = store.of('items');
    return [cache.listMap, cache.resourceMap, cache.resourceAclData].every((m) => Object.keys(m).length === 0);
  }

  describe('of', () => {
    it('returns the same cache for the same name', () => {
      const store = TestBed.inject(RepositoryStore);
      expect(store.of('a')).toBe(store.of('a'));
      expect(store.of('a')).not.toBe(store.of('b'));
    });
  });

  describe('ttl', () => {
    it('defaults to 3 s', () => {
      expect(TestBed.inject(RepositoryStore).ttl()).toBe(DEFAULT_CACHE_TTL);
    });

    it('reads data.cache-ttl at runtime', () => {
      const store = TestBed.inject(RepositoryStore);
      cacheTtl.set(10_000);
      expect(store.ttl()).toBe(10_000);
      cacheTtl.set(0);
      expect(store.ttl()).toBe(0);
    });

    it('prefers the ttl of the entity', () => {
      cacheTtl.set(10_000);
      expect(TestBed.inject(RepositoryStore).ttl(500)).toBe(500);
    });

    it('ignores invalid values', () => {
      cacheTtl.set('soon');
      expect(TestBed.inject(RepositoryStore).ttl(-1)).toBe(DEFAULT_CACHE_TTL);
    });
  });

  describe('clear', () => {
    it('empties every cache in place', () => {
      const store = filled();
      const cache = store.of('items');
      store.clear();
      expect(isEmpty(store)).toBeTrue();
      expect(store.of('items')).toBe(cache);
    });

    it('is not triggered by the initial session state', () => {
      expect(isEmpty(filled())).toBeFalse();
    });

    it('runs when the tenant changes', () => {
      const store = filled();
      tenant.next('main');
      expect(isEmpty(store)).toBeFalse();
      tenant.next('other');
      expect(isEmpty(store)).toBeTrue();
    });

    it('runs on login and logout of any identity', () => {
      const store = filled();
      users['other'].next({ authenticated: true, uid: 'u1' });
      expect(isEmpty(store)).toBeTrue();

      store.of('items').resourceMap['1'] = { cache: {} as any, observers: 1 };
      users['other'].next({ authenticated: true, uid: 'u1', name: 'refreshed profile' });
      expect(isEmpty(store)).toBeFalse();

      users['other'].next(ANONYMOUS_USER);
      expect(isEmpty(store)).toBeTrue();
    });

    it('makes the next query of another user hit the provider', () => {
      const provider = {
        list: jasmine
          .createSpy('list')
          .and.returnValue(of({ hasNext: false, next: null, content: [{ id: '1' }] } as Slide<any>)),
      } as unknown as RepositoryProvider<any, any>;
      const store = TestBed.inject(RepositoryStore);
      const repo = new RepositoryService<any, any>({ key: 'id', name: 'users', provider }, store);
      const open = repo.list({}).subscribe();

      users['main'].next({ authenticated: true, uid: 'u2' });
      repo.list({}).subscribe().unsubscribe();

      expect(provider.list).toHaveBeenCalledTimes(2);
      open.unsubscribe();
    });
  });
});
